package io.robrichardson.lootingbagorganizer.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import io.robrichardson.lootingbagorganizer.LootingBagOrganizerConfig;
import java.util.Arrays;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/** Verifies {@link LayoutStore}'s JSON round-trip and its use of {@link ConfigManager}. */
@RunWith(MockitoJUnitRunner.Silent.class)
public class LayoutStoreTest
{
	private static final String PROFILE = "profile-key";

	@Mock private ConfigManager configManager;
	private LayoutStore store;

	@Before
	public void setUp()
	{
		store = new LayoutStore(configManager, new Gson());
	}

	@Test
	public void saveWritesJsonUnderTheConfigGroupProfileAndLayoutKey()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 42);

		store.save(PROFILE, layout);

		verify(configManager).setConfiguration(
			eq(LootingBagOrganizerConfig.CONFIG_GROUP), eq(PROFILE), eq("layout"), anyString());
	}

	@Test
	public void saveIsNoOpWithoutProfileKey()
	{
		store.save(null, new BagLayout());

		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString(), anyString());
	}

	@Test
	public void loadRoundTripsThroughGson()
	{
		BagLayout original = new BagLayout();
		original.setSlot(0, 1);
		original.setSlot(3, 2);
		original.setSlot(5, 3);

		String json = new Gson().toJson(original);
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn(json);

		BagLayout loaded = store.load(PROFILE);

		assertEquals(original.getSlots(), loaded.getSlots());
	}

	@Test
	public void loadUsesProfileScopedGetConfiguration()
	{
		when(configManager.getConfiguration(eq(LootingBagOrganizerConfig.CONFIG_GROUP), eq(PROFILE), eq("layout")))
			.thenReturn(null);

		store.load(PROFILE);

		verify(configManager).getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout");
	}

	@Test
	public void loadReturnsEmptyLayoutWhenProfileKeyIsNull()
	{
		BagLayout layout = store.load(null);

		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void loadReturnsEmptyLayoutWhenConfigValueIsNull()
	{
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn(null);

		BagLayout layout = store.load(PROFILE);

		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void loadReturnsEmptyLayoutWhenConfigValueIsEmptyString()
	{
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn("");

		BagLayout layout = store.load(PROFILE);

		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void loadReturnsEmptyLayoutOnMalformedJsonWithoutThrowing()
	{
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn("{not valid json!!");

		BagLayout layout = store.load(PROFILE);

		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void loadReturnsEmptyLayoutWhenJsonParsesToNull()
	{
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn("null");

		BagLayout layout = store.load(PROFILE);

		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void loadNormalisesAnOverLengthSavedLayout()
	{
		StringBuilder slots = new StringBuilder("[");
		for (int i = 0; i < 40; i++)
		{
			slots.append(i == 0 ? "" : ",").append(i + 1);
		}
		slots.append("]");
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn("{\"slots\":" + slots + "}");

		BagLayout loaded = store.load(PROFILE);

		assertEquals(BagLayout.SLOTS, loaded.getSlots().size());
	}

	@Test
	public void loadNormalisesTrailingNullsAndNonPositiveIds()
	{
		when(configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, PROFILE, "layout"))
			.thenReturn("{\"slots\":[1,0,-3,4,null,null]}");

		BagLayout loaded = store.load(PROFILE);

		// 0 and -3 canonicalise to null (non-positive ids), and the trailing nulls after slot 3 are
		// dropped, but the null at index 1/2 stays since a later slot (4) is still occupied.
		assertEquals(Arrays.asList(1, null, null, 4), loaded.getSlots());
	}
}

package io.robrichardson.lootingbagorganizer.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class BagLayoutTest
{
	@Test
	public void newLayoutIsEmpty()
	{
		BagLayout layout = new BagLayout();
		assertTrue(layout.getSlots().isEmpty());
		assertEquals(28, BagLayout.SLOTS);
	}

	// -- moveSlot -------------------------------------------------------

	@Test
	public void moveSlotSwapsTwoOccupiedSlots()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		layout.setSlot(1, 200);

		layout.moveSlot(0, 1);

		assertEquals(Integer.valueOf(200), layout.slotAt(0));
		assertEquals(Integer.valueOf(100), layout.slotAt(1));
	}

	@Test
	public void moveSlotMovesIntoAnEmptySlot()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);

		layout.moveSlot(0, 5);

		assertNull(layout.slotAt(0));
		assertEquals(Integer.valueOf(100), layout.slotAt(5));
	}

	@Test
	public void moveSlotIsNoOpWhenFromEqualsTo()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(3, 100);

		layout.moveSlot(3, 3);

		assertEquals(Integer.valueOf(100), layout.slotAt(3));
		// leading/internal nulls are not trimmed, only trailing ones, so the backing list still runs
		// through index 3.
		assertEquals(4, layout.getSlots().size());
	}

	// -- bounds checking --------------------------------------------------

	@Test(expected = IndexOutOfBoundsException.class)
	public void slotAtNegativeIndexThrows()
	{
		new BagLayout().slotAt(-1);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void slotAtTooLargeIndexThrows()
	{
		new BagLayout().slotAt(BagLayout.SLOTS);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void setSlotOutOfRangeThrows()
	{
		new BagLayout().setSlot(BagLayout.SLOTS, 100);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void setSlotNegativeIndexThrows()
	{
		new BagLayout().setSlot(-1, 100);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void clearSlotOutOfRangeThrows()
	{
		new BagLayout().clearSlot(BagLayout.SLOTS);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void moveSlotFromOutOfRangeThrows()
	{
		new BagLayout().moveSlot(BagLayout.SLOTS, 0);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void moveSlotToOutOfRangeThrows()
	{
		new BagLayout().moveSlot(0, BagLayout.SLOTS);
	}

	// -- normalise ----------------------------------------------------------

	@Test
	public void normaliseTruncatesOverLengthList()
	{
		// setSlot/moveSlot never let the backing list exceed SLOTS, but Gson deserialisation (see
		// LayoutStore) sets the private field directly and can hand us an over-length list, so
		// normalise() has to clamp defensively.
		List<Integer> raw = new ArrayList<>();
		for (int i = 0; i < 40; i++)
		{
			// a value at the last in-range index (27) keeps normalise() from trimming it away as a
			// trailing null, so the assertion below is purely about the 40 -> 28 clamp.
			raw.add(i == 27 ? Integer.valueOf(999) : (i >= 28 ? Integer.valueOf(i + 1) : null));
		}
		BagLayout oversized = layoutWithRawSlots(raw);

		oversized.normalise();

		assertEquals(28, oversized.getSlots().size());
		assertEquals(Integer.valueOf(999), oversized.slotAt(27));
	}

	@Test
	public void normaliseStripsTrailingNulls()
	{
		BagLayout layout = layoutWithRawSlots(Arrays.asList(100, null, 200, null, null));
		layout.normalise();
		assertEquals(Arrays.asList(100, null, 200), layout.getSlots());
	}

	@Test
	public void normaliseConvertsNonPositiveIdsToNull()
	{
		BagLayout layout = layoutWithRawSlots(Arrays.asList(100, 0, -5, 200));
		layout.normalise();
		assertEquals(Arrays.asList(100, null, null, 200), layout.getSlots());
	}

	@Test
	public void normaliseOnAlreadyCleanLayoutIsUnchanged()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		layout.setSlot(2, 200);
		layout.normalise();
		assertEquals(Arrays.asList(100, null, 200), layout.getSlots());
	}

	// -- setSlot / clearSlot --------------------------------------------------

	@Test
	public void setSlotWithNonPositiveIdClearsTheSlot()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		layout.setSlot(0, 0);
		assertNull(layout.slotAt(0));
		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void clearSlotFreesAReservation()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		layout.setSlot(1, 200);
		layout.clearSlot(0);
		assertNull(layout.slotAt(0));
		assertEquals(Integer.valueOf(200), layout.slotAt(1));
	}

	@Test
	public void clearSlotPastTheBackingListIsANoOp()
	{
		BagLayout layout = new BagLayout();
		layout.clearSlot(10);
		assertTrue(layout.getSlots().isEmpty());
	}

	@Test
	public void slotAtPastTheBackingListIsFree()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		assertNull(layout.slotAt(10));
	}

	// -- getSlots is unmodifiable ------------------------------------------

	@Test
	public void getSlotsIsUnmodifiable()
	{
		BagLayout layout = new BagLayout();
		layout.setSlot(0, 100);
		try
		{
			layout.getSlots().add(200);
			fail("expected UnsupportedOperationException");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	// -- equals / hashCode ---------------------------------------------------

	@Test
	public void equalLayoutsAreEqualAndHaveSameHashCode()
	{
		BagLayout a = new BagLayout();
		a.setSlot(0, 100);
		a.setSlot(2, 200);

		BagLayout b = new BagLayout();
		b.setSlot(0, 100);
		b.setSlot(2, 200);

		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());
	}

	@Test
	public void equalsComparesNormalisedContent()
	{
		BagLayout a = layoutWithRawSlots(Arrays.asList(100, null, 200, null, null));
		BagLayout b = layoutWithRawSlots(Arrays.asList(100, null, 200));

		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());
	}

	@Test
	public void differentLayoutsAreNotEqual()
	{
		BagLayout a = new BagLayout();
		a.setSlot(0, 100);

		BagLayout b = new BagLayout();
		b.setSlot(0, 200);

		assertFalse(a.equals(b));
	}

	// -- helpers --------------------------------------------------------------

	/**
	 * Builds a layout whose private backing list is exactly {@code raw}, bypassing setSlot's
	 * canonicalisation/trimming entirely. This is what Gson deserialisation does in practice
	 * ({@link LayoutStore}), and is the only way an un-normalised {@link BagLayout} can exist, since
	 * every public mutator keeps the invariant intact.
	 */
	private static BagLayout layoutWithRawSlots(List<Integer> raw)
	{
		BagLayout layout = new BagLayout();
		try
		{
			Field field = BagLayout.class.getDeclaredField("slots");
			field.setAccessible(true);
			@SuppressWarnings("unchecked")
			List<Integer> backing = (List<Integer>) field.get(layout);
			backing.addAll(raw);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
		return layout;
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Covers the full acceptance list for {@link BagDragOverlay}: it draws nothing unless the
 * model reports a drag in progress, it never reads {@link BagInputListener}'s AWT-only state
 * (only {@link BagViewController}'s client-thread-safe getters and its {@link BagViewModel}), and
 * it draws the ghost image plus a target highlight only when there is somewhere sensible to put
 * them.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class BagDragOverlayTest
{
	private static final Rectangle GRID_BOUNDS = new Rectangle(100, 200, 176, 224);
	private static final int ITEM_ID = 1511;

	@Mock private Client client;
	@Mock private ItemManager itemManager;
	@Mock private BagViewController controller;
	@Mock private ItemComposition composition;
	@Mock private AsyncBufferedImage image;

	private BagViewModel model;
	private BagDragOverlay overlay;
	private Graphics2D graphics;

	@Before
	public void setUp()
	{
		model = new BagViewModel();
		model.setGridBounds(GRID_BOUNDS);

		when(controller.getModel()).thenReturn(model);
		when(controller.isViewOpen()).thenReturn(true);
		when(controller.getGridBounds()).thenReturn(GRID_BOUNDS);
		when(controller.getSlots()).thenReturn(Arrays.asList(
			new BagSlot(0, ITEM_ID, 1, BagGeometry.cell(0, GRID_BOUNDS)),
			new BagSlot(1, -1, 0, BagGeometry.cell(1, GRID_BOUNDS))));

		when(client.getItemDefinition(ITEM_ID)).thenReturn(composition);
		when(composition.isStackable()).thenReturn(false);
		when(image.getWidth()).thenReturn(32);
		when(image.getHeight()).thenReturn(32);
		when(itemManager.getImage(anyInt(), anyInt(), org.mockito.ArgumentMatchers.anyBoolean()))
			.thenReturn(image);

		overlay = new BagDragOverlay(client, itemManager, controller);
		graphics = mock(Graphics2D.class);
	}

	@Test
	public void rendersNothingWhenNoDragIsInProgress()
	{
		Dimension size = overlay.render(graphics);

		assertNull(size);
		verifyNoInteractions(graphics);
	}

	@Test
	public void rendersNothingWhenTheViewIsClosedEvenIfTheModelThinksItIsDragging()
	{
		model.beginDrag(0);
		model.updateDrag(new Point(110, 210));
		when(controller.isViewOpen()).thenReturn(false);

		Dimension size = overlay.render(graphics);

		assertNull(size);
		verifyNoInteractions(graphics);
	}

	@Test
	public void drawsTheGhostAndHighlightWhileDraggingOverAnotherCell()
	{
		model.beginDrag(0);
		model.updateDrag(new Point(GRID_BOUNDS.x + 50, GRID_BOUNDS.y + 40));

		overlay.render(graphics);

		verify(graphics).drawImage(org.mockito.ArgumentMatchers.any(java.awt.Image.class),
			anyInt(), anyInt(), org.mockito.ArgumentMatchers.isNull());
		verify(graphics).drawRect(anyInt(), anyInt(), anyInt(), anyInt());
	}

	@Test
	public void drawsNothingOutsideTheGridRectangle()
	{
		model.beginDrag(0);
		// Past the 4x7 pitch rectangle: BagGeometry.slotAt resolves this to -1.
		model.updateDrag(new Point(GRID_BOUNDS.x + 1000, GRID_BOUNDS.y + 1000));

		overlay.render(graphics);

		verify(graphics, never()).drawRect(anyInt(), anyInt(), anyInt(), anyInt());
	}

	@Test
	public void drawsOnlyTheHighlightBeforeTheCursorHasMoved()
	{
		// beginDrag leaves dragPoint null until the first updateDrag; the source cell hovers itself.
		model.beginDrag(0);

		overlay.render(graphics);

		verify(graphics).drawRect(anyInt(), anyInt(), anyInt(), anyInt());
		verify(graphics, never()).drawImage(org.mockito.ArgumentMatchers.any(java.awt.Image.class),
			anyInt(), anyInt(), org.mockito.ArgumentMatchers.isNull());
	}

	@Test
	public void skipsTheGhostWhenTheItemManagerHasNoImageYet()
	{
		when(itemManager.getImage(anyInt(), anyInt(), org.mockito.ArgumentMatchers.anyBoolean()))
			.thenReturn(null);
		model.beginDrag(0);
		model.updateDrag(new Point(GRID_BOUNDS.x + 50, GRID_BOUNDS.y + 40));

		overlay.render(graphics);

		verify(graphics, never()).drawImage(org.mockito.ArgumentMatchers.any(java.awt.Image.class),
			anyInt(), anyInt(), org.mockito.ArgumentMatchers.isNull());
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import static org.junit.Assert.assertEquals;

import java.awt.Rectangle;
import org.junit.Test;

public class BagGeometryTest
{
	@Test
	public void xyMatchGridArithmeticForKnownSlots()
	{
		assertEquals(0, BagGeometry.x(0));
		assertEquals(0, BagGeometry.y(0));

		assertEquals(3 * 44, BagGeometry.x(3));
		assertEquals(0, BagGeometry.y(3));

		assertEquals(0, BagGeometry.x(4));
		assertEquals(32, BagGeometry.y(4));

		assertEquals(3 * 44, BagGeometry.x(27));
		assertEquals(6 * 32, BagGeometry.y(27));
	}

	@Test
	public void xyMatchFormulaForAllSlots()
	{
		for (int i = 0; i < BagGeometry.SLOTS; i++)
		{
			assertEquals((i % 4) * 44, BagGeometry.x(i));
			assertEquals((i / 4) * 32, BagGeometry.y(i));
		}
	}

	@Test
	public void cellIsPositionedRelativeToGridBounds()
	{
		Rectangle gridBounds = new Rectangle(100, 50, 200, 300);
		Rectangle cell = BagGeometry.cell(5, gridBounds);

		assertEquals(gridBounds.x + BagGeometry.x(5), cell.x);
		assertEquals(gridBounds.y + BagGeometry.y(5), cell.y);
		assertEquals(BagGeometry.CELL_W, cell.width);
		assertEquals(BagGeometry.CELL_H, cell.height);
	}

	@Test
	public void slotAtRoundTripsCentreOfEveryCell()
	{
		Rectangle gridBounds = new Rectangle(10, 20, 176, 224);
		for (int slot = 0; slot < BagGeometry.SLOTS; slot++)
		{
			Rectangle cell = BagGeometry.cell(slot, gridBounds);
			int centreX = cell.x + cell.width / 2;
			int centreY = cell.y + cell.height / 2;

			assertEquals("slot " + slot, slot, BagGeometry.slotAt(gridBounds, centreX, centreY));
		}
	}

	@Test
	public void gutterPointMapsToColumnOnItsLeft()
	{
		Rectangle gridBounds = new Rectangle(0, 0, 176, 224);

		// Column 0 cell spans x in [0, 36), gutter is [36, 44). A point in the gutter
		// (e.g. x=40) still belongs to column 0.
		assertEquals(0, BagGeometry.slotAt(gridBounds, 40, 10));

		// Column 1 cell starts at x=44, its gutter is [80, 88).
		assertEquals(1, BagGeometry.slotAt(gridBounds, 84, 10));
	}

	@Test
	public void pointPastColumnFourIsOutside()
	{
		Rectangle gridBounds = new Rectangle(0, 0, 176, 224);

		// Column 3 pitch range is [132, 176); x=176 is past it.
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 176, 10));
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 300, 10));
	}

	@Test
	public void pointPastRowSevenIsOutside()
	{
		Rectangle gridBounds = new Rectangle(0, 0, 176, 224);

		// Row 6 pitch range is [192, 224); y=224 is past it.
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 10, 224));
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 10, 500));
	}

	@Test
	public void pointLeftOrAboveGridIsOutside()
	{
		Rectangle gridBounds = new Rectangle(50, 50, 176, 224);

		assertEquals(-1, BagGeometry.slotAt(gridBounds, 10, 60));
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 60, 10));
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 49, 60));
		assertEquals(-1, BagGeometry.slotAt(gridBounds, 60, 49));
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import io.robrichardson.lootingbagorganizer.model.BagLayout;
import io.robrichardson.lootingbagorganizer.model.LayoutStore;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Drives {@link BagViewController} against a mocked client, in the style of alch-blocker's
 * behaviour test: build the widgets and the container the game would build, run the real
 * client-thread pass, and assert on what was written back to the widgets.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class BagViewControllerTest
{
	private static final int ITEM_A = 1001;
	private static final int ITEM_B = 1002;
	private static final int ITEM_C = 1003;

	private static final Rectangle GRID = new Rectangle(100, 200, 176, 224);

	@Mock private Client client;
	@Mock private ClientThread clientThread;
	@Mock private LayoutStore layoutStore;

	private BagViewController controller;
	private Widget items;
	private Widget title;
	private Cell[] cells;
	private long now = 10_000L;

	/** A stateful stand-in for one dynamic child of 81:5. */
	private static class Cell
	{
		final Widget widget = mock(Widget.class);
		final int index;
		int x;
		int y;
		int revalidations;

		Cell(int index, boolean hidden)
		{
			this.index = index;
			this.x = BagGeometry.x(index);
			this.y = hidden ? 0 : BagGeometry.y(index);
			if (hidden)
			{
				this.x = 0;
			}

			when(widget.isSelfHidden()).thenReturn(hidden);
			when(widget.getOriginalX()).thenAnswer(inv -> x);
			when(widget.getOriginalY()).thenAnswer(inv -> y);
			doAnswer(inv ->
			{
				x = inv.getArgument(0);
				return widget;
			}).when(widget).setOriginalX(anyInt());
			doAnswer(inv ->
			{
				y = inv.getArgument(0);
				return widget;
			}).when(widget).setOriginalY(anyInt());
			doAnswer(inv ->
			{
				revalidations++;
				return null;
			}).when(widget).revalidate();
		}
	}

	@Before
	public void setUp()
	{
		controller = new BagViewController(client, clientThread, layoutStore);
		controller.clock = () -> now;

		items = mock(Widget.class);
		title = mock(Widget.class);
		when(items.isHidden()).thenReturn(false);
		when(items.getBounds()).thenReturn(GRID);
		when(title.getText()).thenReturn("Looting bag");
		when(client.getWidget(InterfaceID.WildernessLootingbag.ITEMS)).thenReturn(items);
		when(client.getWidget(InterfaceID.WildernessLootingbag.TITLE)).thenReturn(title);

		doAnswer(inv ->
		{
			((Runnable) inv.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		when(layoutStore.load(any())).thenReturn(new BagLayout());
	}

	/** Builds 28 children, the first {@code occupied} of them visible, like script 497 does. */
	private void giveChildren(int occupied)
	{
		cells = new Cell[BagLayout.SLOTS];
		Widget[] children = new Widget[BagLayout.SLOTS];
		for (int i = 0; i < BagLayout.SLOTS; i++)
		{
			cells[i] = new Cell(i, i >= occupied);
			children[i] = cells[i].widget;
		}
		when(items.getDynamicChildren()).thenReturn(children);
	}

	private void giveContainer(int... ids)
	{
		ItemContainer container = mock(ItemContainer.class);
		Item[] contents = new Item[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			contents[i] = new Item(ids[i], 1);
		}
		when(container.getItems()).thenReturn(contents);
		when(client.getItemContainer(InventoryID.LOOTING_BAG)).thenReturn(container);
	}

	private void openBagWith(int... ids)
	{
		giveChildren(ids.length);
		giveContainer(ids);
	}

