/**
 * Drives the plugin through its real event handlers and lifecycle against a mocked client, so the
 * wiring in {@link LootingBagOrganizerPlugin} is verified without a logged-in game. Style copied
 * from {@code alch-blocker}'s {@code AlchBlockerPluginBehaviourTest}.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class LootingBagOrganizerPluginBehaviourTest
{
	private static final int BUILD_SCRIPT = 497;
	private static final String PROFILE = "rsprofile.abc";

	@Mock private Client client;
	@Mock private ClientThread clientThread;
	@Mock private ConfigManager configManager;
	@Mock private OverlayManager overlayManager;
	@Mock private MouseManager mouseManager;
	@Mock private KeyManager keyManager;
	@Mock private BagViewController viewController;
	@Mock private BagInputListener inputListener;
	@Mock private BagDragOverlay dragOverlay;

	@InjectMocks private LootingBagOrganizerPlugin plugin;

	@Before
	public void setUp()
	{
		// Client-thread work runs immediately.
		doAnswer(inv ->
		{
			((Runnable) inv.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
	}

	@Test
	public void startUpRegistersTheOverlayTheMouseListenerAtPositionZeroAndTheKeyListener() throws Exception
	{
		plugin.startUp();

		verify(viewController).startUp();
		verify(overlayManager).add(dragOverlay);
		verify(mouseManager).registerMouseListener(eq(0), eq(inputListener));
		verify(keyManager).registerKeyListener(inputListener);
	}

	@Test
	public void shutDownRestoresThroughTheControllerThenUnregistersEverything() throws Exception
	{
		plugin.startUp();
		plugin.shutDown();

		// The controller's shutDown flushes the pending save and posts restoreGameOrder.
		verify(viewController).shutDown();
		verify(overlayManager).remove(dragOverlay);
		verify(mouseManager).unregisterMouseListener(inputListener);
		verify(keyManager).unregisterKeyListener(inputListener);
	}

	@Test
	public void registeringShuttingDownAndReRegisteringLeavesExactlyOneMouseListener() throws Exception
	{
		plugin.startUp();
		plugin.shutDown();
		plugin.startUp();

		verify(mouseManager, times(2)).registerMouseListener(0, inputListener);
		verify(mouseManager, times(1)).unregisterMouseListener(inputListener);
		verify(keyManager, times(2)).registerKeyListener(inputListener);
		verify(keyManager, times(1)).unregisterKeyListener(inputListener);
	}

	@Test
	public void aSecondStartUpWithoutAShutDownDoesNotDoubleRegister() throws Exception
	{
		plugin.startUp();
		plugin.startUp();

		verify(mouseManager, times(1)).registerMouseListener(0, inputListener);
		verify(keyManager, times(1)).registerKeyListener(inputListener);
	}

	@Test
	public void startingWhileAlreadyLoggedInLoadsTheProfileImmediately() throws Exception
	{
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);

		plugin.startUp();

		verify(viewController).onProfileChanged(PROFILE);
	}

	@Test
	public void startingAtTheLoginScreenDoesNotLoadAProfile() throws Exception
	{
		plugin.startUp();

		verify(viewController, never()).onProfileChanged(any());
	}

	@Test
	public void clientTickDrivesTheControllerPass()
	{
		plugin.onClientTick(new ClientTick());

		verify(viewController).tick();
	}

	@Test
	public void theGridBuildScriptMarksUsDirty()
	{
		plugin.onScriptPostFired(new ScriptPostFired(BUILD_SCRIPT));

		verify(viewController).markDirty();
	}

	@Test
	public void anUnrelatedScriptIsIgnored()
	{
		plugin.onScriptPostFired(new ScriptPostFired(BUILD_SCRIPT + 1));

		verifyNoInteractions(viewController);
	}

	@Test
	public void aLootingBagContainerChangeMarksUsDirty()
	{
		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.LOOTING_BAG, null));

		verify(viewController).markDirty();
	}

	@Test
	public void anotherContainerIsIgnored()
	{
		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, null));

		verifyNoInteractions(viewController);
	}

	@Test
	public void loadingGroup81MarksUsDirty()
	{
		plugin.onWidgetLoaded(widgetLoaded(InterfaceID.WILDERNESS_LOOTINGBAG));

		verify(viewController).markDirty();
	}

	@Test
	public void loadingAnotherGroupIsIgnored()
	{
		plugin.onWidgetLoaded(widgetLoaded(InterfaceID.BANKMAIN));

		verifyNoInteractions(viewController);
	}

	@Test
	public void closingGroup81CancelsAnyDrag()
	{
		plugin.onWidgetClosed(new WidgetClosed(InterfaceID.WILDERNESS_LOOTINGBAG, 3, true));

		verify(viewController).cancelDrag();
	}

	@Test
	public void closingAnotherGroupIsIgnored()
	{
		plugin.onWidgetClosed(new WidgetClosed(InterfaceID.BANKMAIN, 3, true));

		verifyNoInteractions(viewController);
	}

	@Test
	public void loggingInLoadsTheLayoutForTheRsProfile()
	{
		plugin.onGameStateChanged(gameState(GameState.LOGGED_IN));

		verify(viewController).onProfileChanged(PROFILE);
	}

	@Test
	public void otherGameStatesDoNotLoadALayout()
	{
		plugin.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		plugin.onGameStateChanged(gameState(GameState.HOPPING));

		verify(viewController, never()).onProfileChanged(any());
	}

	@Test
	public void aProfileChangeLoadsTheNewProfileOnTheClientThread()
	{
		when(configManager.getRSProfileKey()).thenReturn("rsprofile.other");

		plugin.onRuneScapeProfileChanged(new RuneScapeProfileChanged(PROFILE, "rsprofile.other"));

		verify(clientThread).invoke(any(Runnable.class));
		verify(viewController).onProfileChanged("rsprofile.other");
	}

	@Test
	public void theBuildScriptConstantIsFourNineSeven()
	{
		// docs/RESEARCH.md section 2: script 497 is the cc_deleteall + rebuild of 81:5.
		assertEquals(497, BUILD_SCRIPT);
	}

	private static GameStateChanged gameState(GameState state)
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		return event;
	}

	private static WidgetLoaded widgetLoaded(int groupId)
	{
		WidgetLoaded event = new WidgetLoaded();
		event.setGroupId(groupId);
		return event;
	}
}

package io.robrichardson.lootingbagorganizer;

import com.google.inject.Provides;
import io.robrichardson.lootingbagorganizer.ui.BagDragOverlay;
import io.robrichardson.lootingbagorganizer.ui.BagInputListener;
import io.robrichardson.lootingbagorganizer.ui.BagViewController;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * DI wiring, lifecycle and event fan-out. Everything this class does is either registration or
 * forwarding: the arrangement itself lives in {@link BagViewController} (client thread) and
 * {@link BagInputListener} (AWT thread).
 *
 * <p>Nothing here changes what the bag contains and nothing fires a game action; the layout is
 * cosmetic and lives in our own config (see {@code docs/RESEARCH.md} section 1: "There is no
 * server-side reorder action. Every arrangement is cosmetic and lives in our config.").
 *
 * <p>Logging is deliberately verbose at debug level per the board decision: {@code runClient} runs
 * with {@code --debug}, so a manual test session leaves a log we can debug from. Every lifecycle
 * and event edge logs its identifying detail (script id, container id, group id, modal mode).
 */
@Slf4j
@PluginDescriptor(
	name = "Looting Bag Organizer",
	description = "Drag items around inside the looting bag view to arrange them how you like. Client-side only.",
	tags = {"uim", "looting bag", "inventory", "items", "layout", "organize"}
)
public class LootingBagOrganizerPlugin extends Plugin
{
	/**
	 * The clientscript that rebuilds the bag grid: {@code cc_deleteall} on 81:5 then one dynamic
	 * child per container slot, which resets every position we set. It runs on every transmit of
	 * container 516, so the layout is re-applied after every firing rather than once on open.
	 * There is no {@code ScriptID} constant for it; see {@code docs/RESEARCH.md} section 2, which
	 * dumped it out of the live cache. Verify with the Script Inspector under
	 * {@code --developer-mode} (see {@code docs/TESTING.md}).
	 */
	private static final int SCRIPT_LOOTING_BAG_BUILD_ITEMS = 497;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private BagViewController viewController;

	@Inject
	private BagInputListener inputListener;

	@Inject
	private BagDragOverlay dragOverlay;

	/**
	 * {@code MouseManager.registerMouseListener} does not de-duplicate, so registration is guarded
	 * and always torn down in {@link #shutDown()}.
	 */
	private boolean listenersRegistered;

	@Provides
	LootingBagOrganizerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LootingBagOrganizerConfig.class);
	}

	@Override
	protected void startUp()
	{
		viewController.startUp();

		overlayManager.add(dragOverlay);
		if (!listenersRegistered)
		{
			mouseManager.registerMouseListener(0, inputListener);
			keyManager.registerKeyListener(inputListener);
			listenersRegistered = true;
		}

		// Enabled mid-session: no RuneScapeProfileChanged or LOGGED_IN is coming, so load now.
		GameState gameState = client.getGameState();
		if (gameState == GameState.LOGGED_IN)
		{
			loadProfile("startUp");
		}

		log.debug("Looting Bag Organizer started (gameState={}, listeners registered={})",
			gameState, listenersRegistered);
	}

	@Override
	protected void shutDown()
	{
		// Restore first: the controller flushes a pending save and puts the game's own cell order
		// and title back on the client thread, so a disabled plugin leaves no trace.
		viewController.shutDown();

		overlayManager.remove(dragOverlay);
		if (listenersRegistered)
		{
			mouseManager.unregisterMouseListener(inputListener);
			keyManager.unregisterKeyListener(inputListener);
			listenersRegistered = false;
		}

		log.debug("Looting Bag Organizer stopped");
	}

	/**
	 * The client-thread pass: drains the queue the AWT listener posts to, re-applies the layout if
	 * anything marked it dirty, publishes the volatiles the AWT tier reads. Uses {@code ClientTick}
	 * rather than the overlay's render so the queue is drained even on the frame the window closes.
	 * Not logged: it fires every frame.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		viewController.tick();
	}

	/**
	 * The precise "the grid was just rebuilt" signal. Every firing wipes the positions we set, so
	 * every firing marks us dirty.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == SCRIPT_LOOTING_BAG_BUILD_ITEMS)
		{
			log.debug("Script {} fired: looting bag grid rebuilt, re-applying layout",
				event.getScriptId());
			viewController.markDirty();
		}
	}

	/** Belt and braces alongside script 497: the container transmit that makes 497 run. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.LOOTING_BAG)
		{
			log.debug("Item container {} changed: re-applying layout", event.getContainerId());
			viewController.markDirty();
		}
	}

	/** Belt and braces: the interface opened, whether or not the script id is still 497. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.WILDERNESS_LOOTINGBAG)
		{
			log.debug("Widget group {} loaded: re-applying layout", event.getGroupId());
			viewController.markDirty();
		}
	}

	/**
	 * The widgets are going away, so any in-flight drag is meaningless. The modal mode is logged
	 * because {@code docs/TESTING.md} section 2 needs it confirmed at runtime (expected 3,
	 * MODAL_CLICKTHROUGH).
	 */
	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.WILDERNESS_LOOTINGBAG)
		{
			log.debug("Widget group {} closed (modalMode={}, unload={}): cancelling any drag",
				event.getGroupId(), event.getModalMode(), event.isUnload());
			viewController.cancelDrag();
		}
	}

	/**
	 * The RS profile key is only stable once logged in; loading on both this and
	 * {@code RuneScapeProfileChanged} is safe because the controller ignores a repeat of the key
	 * it already has.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		log.debug("Game state changed to {}", event.getGameState());
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfile("GameStateChanged");
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		log.debug("RS profile changed: {} -> {}", event.getPreviousProfile(), event.getNewProfile());
		loadProfile("RuneScapeProfileChanged");
	}

	/**
	 * Loads (and saves the outgoing) layout for whatever RS profile the config manager reports.
	 * Routed through the client thread because the model is client-thread only and
	 * {@code RuneScapeProfileChanged} can be posted from a config write on any thread.
	 */
	private void loadProfile(String reason)
	{
		String profileKey = configManager.getRSProfileKey();
		log.debug("Profile load requested by {}: rsProfileKey={}", reason, profileKey);
		clientThread.invoke(() -> viewController.onProfileChanged(profileKey));
	}
}

package io.robrichardson.lootingbagorganizer.model;

import com.google.gson.Gson;
import io.robrichardson.lootingbagorganizer.LootingBagOrganizerConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Loads and saves a {@link BagLayout} as one JSON value under the RS-profile-scoped key
 * {@link #KEY} in config group {@code lootingbagorganizer}. RS-profile keys always sync with a
 * signed-in RuneLite account, so the arrangement follows the character, not the machine.
 */
@Slf4j
@Singleton
public class LayoutStore
{
	static final String KEY = "layout";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public LayoutStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * @param profileKey the RS profile key, from {@code configManager.getRSProfileKey()}. A
	 * {@code null} key (not yet resolved) returns a fresh, empty layout rather than throwing.
	 */
	public BagLayout load(String profileKey)
	{
		String json = profileKey == null ? null
			: configManager.getConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, profileKey, KEY);
		if (json == null || json.isEmpty())
		{
			return new BagLayout();
		}

		try
		{
			BagLayout layout = gson.fromJson(json, BagLayout.class);
			if (layout == null)
			{
				return new BagLayout();
			}
			layout.normalise();
			return layout;
		}
		catch (RuntimeException e)
		{
			// JsonSyntaxException for malformed JSON, but also anything normalise() cannot repair. A
			// fresh layout beats letting the exception escape into the render loop, where it would
			// recur every frame.
			log.warn("Discarding unreadable looting bag layout for profile {}", profileKey, e);
			return new BagLayout();
		}
	}

	public void save(String profileKey, BagLayout layout)
	{
		if (profileKey == null)
		{
			return;
		}

		configManager.setConfiguration(LootingBagOrganizerConfig.CONFIG_GROUP, profileKey, KEY, gson.toJson(layout));
	}
}

package io.robrichardson.lootingbagorganizer.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The player's chosen arrangement of the looting bag: which item sits in which of the 28 slots.
 *
 * <p>Pure data, no RuneLite imports. Persisted as JSON per RS profile by {@link LayoutStore}.
 *
 * <p>Slots are sparse: {@code null} is a deliberate empty slot, trailing nulls are never stored.
 * The bag can hold several non-stackable copies of one id, so a slot is addressed by index, never
 * looked up by id alone (see {@code docs/RESEARCH.md} section 4, "Duplicate ids").
 */
public class BagLayout
{
	public static final int SLOTS = 28;

	private final List<Integer> slots = new ArrayList<>();

	public List<Integer> getSlots()
	{
		return Collections.unmodifiableList(slots);
	}

	/**
	 * @param index slot index, {@code 0 <= index < SLOTS}
	 * @return the reserved item id at {@code index}, or {@code null} if the slot is free. Reading
	 * past the end of the sparse backing list is the same as reading a free slot.
	 */
	public Integer slotAt(int index)
	{
		checkIndex(index);
		return index < slots.size() ? slots.get(index) : null;
	}

	/**
	 * Reserves {@code index} for {@code itemId}, or frees it if {@code itemId} is {@code null} or
	 * not a positive id.
	 */
	public void setSlot(int index, Integer itemId)
	{
		checkIndex(index);
		ensureCapacity(index + 1);
		slots.set(index, canonicalise(itemId));
		trimTrailingNulls();
	}

	public void clearSlot(int index)
	{
		checkIndex(index);
		if (index < slots.size())
		{
			slots.set(index, null);
			trimTrailingNulls();
		}
	}

	/**
	 * Swaps the entries at {@code from} and {@code to}. A no-op when {@code from == to}.
	 */
	public void moveSlot(int from, int to)
	{
		checkIndex(from);
		checkIndex(to);
		if (from == to)
		{
			return;
		}
		ensureCapacity(Math.max(from, to) + 1);
		Integer temp = slots.get(from);
		slots.set(from, slots.get(to));
		slots.set(to, temp);
		trimTrailingNulls();
	}

	/**
	 * Repairs anything a saved layout can get wrong: over-length lists, trailing nulls, negative or
	 * zero ids. Always call after deserialising.
	 */
	public void normalise()
	{
		List<Integer> normalised = normalisedSlots();
		slots.clear();
		slots.addAll(normalised);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BagLayout))
		{
			return false;
		}
		BagLayout other = (BagLayout) o;
		return normalisedSlots().equals(other.normalisedSlots());
	}

	@Override
	public int hashCode()
	{
		return normalisedSlots().hashCode();
	}

	private static void checkIndex(int index)
	{
		if (index < 0 || index >= SLOTS)
		{
			throw new IndexOutOfBoundsException("slot index " + index + " out of range [0, " + SLOTS + ")");
		}
	}

	private static Integer canonicalise(Integer itemId)
	{
		return (itemId != null && itemId <= 0) ? null : itemId;
	}

	private void ensureCapacity(int size)
	{
		while (slots.size() < size)
		{
			slots.add(null);
		}
	}

	private void trimTrailingNulls()
	{
		int end = slots.size();
		while (end > 0 && slots.get(end - 1) == null)
		{
			end--;
		}
		while (slots.size() > end)
		{
			slots.remove(slots.size() - 1);
		}
	}

	/**
	 * Clamped to {@link #SLOTS} entries, negative/zero ids converted to {@code null}, trailing
	 * nulls dropped. Does not mutate {@link #slots}.
	 */
	private List<Integer> normalisedSlots()
	{
		int end = Math.min(slots.size(), SLOTS);
		List<Integer> result = new ArrayList<>(end);
		for (int i = 0; i < end; i++)
		{
			result.add(canonicalise(slots.get(i)));
		}
		int trimmedEnd = result.size();
		while (trimmedEnd > 0 && result.get(trimmedEnd - 1) == null)
		{
			trimmedEnd--;
		}
		return new ArrayList<>(result.subList(0, trimmedEnd));
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import io.robrichardson.lootingbagorganizer.model.BagLayout;
import io.robrichardson.lootingbagorganizer.model.LayoutStore;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

/**
 * The seam between RuneLite and the pure tier. Client-thread owner of {@link BagViewModel}.
 *
 * <p>Every pass ({@link #tick()}, driven by {@code ClientTick}) drains the action queue the AWT
 * input listener posts to, then, if something marked us dirty, reads container 516 and the
 * dynamic children of {@code WildernessLootingbag.ITEMS} (81:5), asks the model where each item
 * goes, and re-positions the children the game built with {@code setOriginalX/Y} +
 * {@code revalidate()}. That is the core {@code banktags} {@code LayoutManager} pattern: no
 * widget is ever created, no item is moved in the container, no game action is fired.
 *
 * <p>Script 497 rebuilds the grid from scratch on every transmit of container 516, resetting all
 * positions, so the layout is re-applied after every rebuild rather than once on open (see
 * {@code docs/RESEARCH.md} section 2, "Verdict for the looting bag: feasible").
 *
 * <p>Threading: the model and every {@code Client}/{@code Widget} access is client thread only.
 * The AWT tier reads the {@code volatile} fields published here ({@link #isViewOpen()},
 * {@link #getGridBounds()}, {@link #getSlots()}) and writes nothing but {@link #post(Runnable)}.
 *
 * <p>Logging is deliberately verbose at debug level: {@code runClient} runs with {@code --debug},
 * so a manual test session leaves a log we can debug the arrangement from.
 */
@Slf4j
@Singleton
public class BagViewController
{
	/**
	 * The deposit flow ("Add to bag") is the same interface group as the View window; only the
	 * TITLE (81:1) text tells them apart, as DWMS does. Compared lower-case and as a prefix so a
	 * colour tag or a trailing count cannot fool it.
	 */
	static final String DEPOSIT_TITLE = "add to bag";

	/** The game's own title, restored on {@link #restoreGameOrder()} so a disabled plugin leaves no trace. */
	static final String BASE_TITLE = "Looting bag";

	private static final int SLOTS = BagLayout.SLOTS;
	private static final long SAVE_INTERVAL_MS = 1000L;
	private static final Rectangle NO_BOUNDS = new Rectangle();

	private final Client client;
	private final ClientThread clientThread;
	private final LayoutStore layoutStore;
	private final BagViewModel model = new BagViewModel();
	private final ConcurrentLinkedQueue<Runnable> actions = new ConcurrentLinkedQueue<>();

	/**
	 * The positions the game gave each cell, remembered per widget instance. Script 497 deletes
	 * and recreates the children on every rebuild, so a changed instance at an index is how we
	 * know a capture is stale.
	 */
	private final Widget[] capturedChildren = new Widget[SLOTS];
	private final int[] capturedX = new int[SLOTS];
	private final int[] capturedY = new int[SLOTS];

	private boolean started;
	private boolean dirty;
	private boolean layoutDirty;
	private long lastSaveMs;
	private String profileKey;
	private String lastSkipReason;

	/** Package-private seam so the save-coalescing test does not have to sleep. */
	LongSupplier clock = System::currentTimeMillis;

	private volatile boolean viewOpen;
	private volatile Rectangle gridBounds = NO_BOUNDS;
	private volatile List<BagSlot> slots = Collections.emptyList();

	@Inject
	public BagViewController(Client client, ClientThread clientThread, LayoutStore layoutStore)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.layoutStore = layoutStore;
	}

	public BagViewModel getModel()
	{
		return model;
	}

	// ---- lifecycle -----------------------------------------------------------------------------

	/** Client thread. Arms the controller; the first {@link #tick()} applies whatever is on screen. */
	public void startUp()
	{
		started = true;
		dirty = true;
		lastSaveMs = clock.getAsLong();
		log.debug("BagViewController started");
	}

	/**
	 * Saves any pending layout change, then restores the game's own cell order on the client
	 * thread so a disabled plugin leaves no trace (see {@code docs/RESEARCH.md} section 2,
	 * "Restoring on shutdown").
	 */
	public void shutDown()
	{
		log.debug("BagViewController stopping (layoutDirty={}, profile={})", layoutDirty, profileKey);
		started = false;
		actions.clear();
		saveNow();
		clientThread.invoke(this::restoreGameOrder);
	}

	// ---- action queue --------------------------------------------------------------------------

	/** Any thread (in practice AWT). Runs on the client thread at the top of the next pass. */
	public void post(Runnable action)
	{
		if (action != null)
		{
			actions.add(action);
		}
	}

	/** Client thread. Runs everything the input listener queued since the last pass, in order. */
	void drainActions()
	{
		Runnable action;
		while ((action = actions.poll()) != null)
		{
			try
			{
				action.run();
			}
			catch (RuntimeException e)
			{
				// A failing input action must never break the frame, or it recurs forever.
				log.warn("Looting bag action failed", e);
			}
		}
	}

	// ---- the client-thread pass ----------------------------------------------------------------

	/**
	 * Client thread, once per frame from {@code ClientTick}. Drains the queue, re-applies the
	 * layout if anything marked us dirty, publishes the volatiles the AWT tier reads, and flushes
	 * a pending layout save at most once a second.
	 */
	public void tick()
	{
		drainActions();

		if (!started)
		{
			return;
		}

		Widget items = client.getWidget(InterfaceID.WildernessLootingbag.ITEMS);
		boolean open = items != null && !items.isHidden() && !isDepositFlow();

		if (open)
		{
			gridBounds = boundsOf(items);
			if (dirty && applyLayout(items))
			{
				// Only a pass that actually re-positioned something consumes the dirty flag. A pass
				// that bailed out (container not transmitted yet, script 497 not run yet) has to be
				// retried, or the one signal we were given is lost for this open window.
				dirty = false;
			}
		}
		else
		{
			if (viewOpen)
			{
				log.debug("Looting bag view no longer open; clearing published state");
			}
			gridBounds = NO_BOUNDS;
			slots = Collections.emptyList();
			model.cancelDrag();
		}

		viewOpen = open;
		model.setGridBounds(gridBounds);
		saveIfDue();
	}

	/** Ask for the layout to be re-applied on the next pass. Cheap and idempotent. */
	public void markDirty()
	{
		dirty = true;
	}

	/**
	 * Client thread. Loads the layout for a new RS profile key, saving the outgoing one first.
	 * A repeat of the current key is a no-op, so it is safe to call from both
	 * {@code RuneScapeProfileChanged} and {@code GameStateChanged(LOGGED_IN)}.
	 */
	public void onProfileChanged(String newProfileKey)
	{
		if (Objects.equals(newProfileKey, profileKey))
		{
			return;
		}

		saveNow();
		profileKey = newProfileKey;
		BagLayout loaded = layoutStore.load(newProfileKey);
		model.setLayout(loaded);
		layoutDirty = false;
		lastSaveMs = clock.getAsLong();
		markDirty();
		log.debug("Loaded looting bag layout for profile {}: {}", newProfileKey, loaded.getSlots());
	}

	public String getProfileKey()
	{
		return profileKey;
	}

	// ---- drag, from the posted runnables --------------------------------------------------------

	/** Client thread. Starts a drag from a display slot. */
	public void beginDrag(int sourceSlot)
	{
		log.debug("Drag begin from slot {}", sourceSlot);
		model.beginDrag(sourceSlot);
	}

	/** Client thread. Tracks the cursor during a drag. */
	public void updateDrag(Point canvasPoint)
	{
		model.updateDrag(canvasPoint);
	}

	/**
	 * Client thread. Resolves a drop; a changed layout is marked dirty for both re-application and
	 * persistence.
	 */
	public void endDrag(int targetSlot)
	{
		int source = model.getDragSource();
		boolean changed = model.endDrag(targetSlot);
		log.debug("Drag end {} -> {} (layout changed: {}, slots frozen: {})", source, targetSlot, changed,
			model.getLastFreezeCount());
		if (changed)
		{
			layoutDirty = true;
			markDirty();
		}
	}

	/** Client thread. Drops any in-flight drag; the layout is untouched. */
	public void cancelDrag()
	{
		if (model.isDragging())
		{
			log.debug("Drag cancelled (source slot {})", model.getDragSource());
		}
		model.cancelDrag();
	}

	// ---- published state for the AWT tier --------------------------------------------------------

	/** True while the View window (not the "Add to bag" deposit flow) is on screen. */
	public boolean isViewOpen()
	{
		return viewOpen;
	}

	/** Canvas bounds of the grid layer (81:5), or an empty rectangle while the view is closed. */
	public Rectangle getGridBounds()
	{
		Rectangle published = gridBounds;
		return new Rectangle(published);
	}

	/**
	 * The last applied arrangement, indexed by display slot: what item each cell shows and where
	 * it is on the canvas. Empty while the view is closed.
	 */
	public List<BagSlot> getSlots()
	{
		return slots;
	}

	// ---- apply and restore -----------------------------------------------------------------------

	/**
	 * Client thread. Reads container 516, resolves display slots and re-positions each visible
	 * dynamic child of 81:5. Hidden children (the game's empty cells) are left exactly as the game
	 * left them; nothing is unhidden, resized, re-itemed or re-opped.
	 *
	 * @return {@code true} if the layout was applied; {@code false} if the frame was not ready, in
	 * which case the caller keeps the dirty flag and retries next pass
	 */
	private boolean applyLayout(Widget items)
	{
		ItemContainer container = client.getItemContainer(InventoryID.LOOTING_BAG);
		if (container == null)
		{
			logSkipOnce("Apply skipped: container " + InventoryID.LOOTING_BAG + " is null");
			return false;
		}

		Widget[] children = items.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			logSkipOnce("Apply skipped: 81:5 has no dynamic children yet");
			return false;
		}

		lastSkipReason = null;

		int[] ids = new int[SLOTS];
		int[] quantities = new int[SLOTS];
		Item[] contents = container.getItems();
		for (int i = 0; i < SLOTS; i++)
		{
			Item item = contents != null && i < contents.length ? contents[i] : null;
			ids[i] = item == null ? -1 : item.getId();
			quantities[i] = item == null ? 0 : item.getQuantity();
		}
		log.debug("Bag snapshot from container {}: {}", InventoryID.LOOTING_BAG, describeSnapshot(ids, quantities));

		int[] target = model.arrange(ids);
		if (model.consumeLayoutChanged())
		{
			layoutDirty = true;
			log.debug("Arrange dropped a stale reservation; layout marked for saving");
		}
		log.debug("Arrange result (containerIndex->slot): {}", describeArrangement(ids, target));

		Rectangle bounds = boundsOf(items);
		List<BagSlot> published = new ArrayList<>(SLOTS);
		for (int slot = 0; slot < SLOTS; slot++)
		{
			published.add(new BagSlot(slot, -1, 0, BagGeometry.cell(slot, bounds)));
		}

		int moved = 0;
		for (int i = 0; i < children.length && i < SLOTS; i++)
		{
			Widget child = children[i];
			if (child == null)
			{
				continue;
			}

			captureGameOrder(i, child);

			if (child.isSelfHidden())
			{
				// An empty cell: hidden at 0x0 by script 497. Leave it alone entirely.
				continue;
			}

			int slot = target[i];
			if (slot < 0 || slot >= SLOTS)
			{
				continue;
			}

			child.setOriginalX(BagGeometry.x(slot));
			child.setOriginalY(BagGeometry.y(slot));
			child.revalidate();
			moved++;

			published.set(slot, new BagSlot(slot, ids[i], quantities[i], BagGeometry.cell(slot, bounds)));
		}

		slots = Collections.unmodifiableList(published);
		log.debug("Applied layout: {} of {} children re-positioned, grid bounds {}", moved, children.length, bounds);

		int taken = 0;
		for (int id : ids)
		{
			if (id > 0)
			{
				taken++;
			}
		}
		updateTitle(taken);
		return true;
	}

	/**
	 * A skipped apply now stays dirty, so the same reason would otherwise log every frame. Logged
	 * only when the reason changes.
	 */
	private void logSkipOnce(String reason)
	{
		if (!reason.equals(lastSkipReason))
		{
			lastSkipReason = reason;
			log.debug("{}", reason);
		}
	}

	/**
	 * Client thread. Puts every visible cell back where the game had it: the position we captured
	 * before touching it, or the game's own arithmetic {@code (i % 4) * 44, (i / 4) * 32} when we
	 * have no capture for that child. Called from {@link #shutDown()}; safe if 81:5 is already gone.
	 */
	public void restoreGameOrder()
	{
		viewOpen = false;
		gridBounds = NO_BOUNDS;
		slots = Collections.emptyList();
		model.cancelDrag();

		Widget items = client.getWidget(InterfaceID.WildernessLootingbag.ITEMS);
		Widget[] children = items == null ? null : items.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			log.debug("Restore skipped: 81:5 is gone or has no children");
			clearCaptures();
			resetTitle();
			return;
		}

		int restored = 0;
		for (int i = 0; i < children.length && i < SLOTS; i++)
		{
			Widget child = children[i];
			if (child == null || child.isSelfHidden())
			{
				continue;
			}

			boolean captured = capturedChildren[i] == child;
			int x = captured ? capturedX[i] : BagGeometry.x(i);
			int y = captured ? capturedY[i] : BagGeometry.y(i);
			child.setOriginalX(x);
			child.setOriginalY(y);
			child.revalidate();
			restored++;
		}

		clearCaptures();
		resetTitle();
		log.debug("Restored the game's own cell order for {} children", restored);
	}

	// ---- persistence -----------------------------------------------------------------------------

	/** Client thread. Writes the layout at most once a second while it is dirty. */
	private void saveIfDue()
	{
		if (!layoutDirty || profileKey == null)
		{
			return;
		}

		long now = clock.getAsLong();
		if (now - lastSaveMs < SAVE_INTERVAL_MS)
		{
			return;
		}

		lastSaveMs = now;
		layoutDirty = false;
		layoutStore.save(profileKey, model.getLayout());
		log.debug("Saved looting bag layout for profile {}: {}", profileKey, model.getLayout().getSlots());
	}

	/** Client thread. Writes a pending change immediately, ignoring the coalescing window. */
	private void saveNow()
	{
		if (!layoutDirty || profileKey == null)
		{
			return;
		}

		layoutDirty = false;
		lastSaveMs = clock.getAsLong();
		layoutStore.save(profileKey, model.getLayout());
		log.debug("Flushed looting bag layout for profile {}: {}", profileKey, model.getLayout().getSlots());
	}

	// ---- helpers ---------------------------------------------------------------------------------

	/**
	 * The deposit flow retitles the window "Add to bag" (script 495). It must be left completely
	 * alone: no re-positioning, and the input listener never arms while this is true.
	 */
	private boolean isDepositFlow()
	{
		Widget title = client.getWidget(InterfaceID.WildernessLootingbag.TITLE);
		String text = title == null ? null : title.getText();
		if (text == null)
		{
			return false;
		}
		return text.toLowerCase().contains(DEPOSIT_TITLE);
	}

	/**
	 * Client thread. Re-texts TITLE (81:1) with the taken/free count. Only ever called after an
	 * apply, so never on the deposit flow and never with a null container. Only {@code setText} is
	 * touched; no listener on the widget is added or removed.
	 */
	private void updateTitle(int taken)
	{
		Widget title = client.getWidget(InterfaceID.WildernessLootingbag.TITLE);
		if (title == null)
		{
			return;
		}

		String text = titleText(taken);
		title.setText(text);
		log.debug("Set looting bag title to '{}'", text);
	}

	/** Client thread. Puts the game's own title back, e.g. on {@link #shutDown()}. */
	private void resetTitle()
	{
		Widget title = client.getWidget(InterfaceID.WildernessLootingbag.TITLE);
		if (title == null)
		{
			return;
		}

		String current = title.getText();
		if (current != null && current.toLowerCase().contains(DEPOSIT_TITLE))
		{
			// Shutting down with the deposit dialog open: we never wrote this title, so relabelling
			// it "Looting bag" would be the trace we are here to avoid.
			return;
		}

		title.setText(BASE_TITLE);
		log.debug("Restored looting bag title to '{}'", BASE_TITLE);
	}

	/** Pure. {@code "Looting bag (n/28)"}. */
	static String titleText(int taken)
	{
		return BASE_TITLE + " (" + taken + "/" + SLOTS + ")";
	}

	private void captureGameOrder(int index, Widget child)
	{
		if (capturedChildren[index] == child)
		{
			return;
		}

		capturedChildren[index] = child;
		capturedX[index] = child.getOriginalX();
		capturedY[index] = child.getOriginalY();
	}

	private void clearCaptures()
	{
		for (int i = 0; i < SLOTS; i++)
		{
			capturedChildren[i] = null;
			capturedX[i] = 0;
			capturedY[i] = 0;
		}
	}

	private static Rectangle boundsOf(Widget widget)
	{
		Rectangle bounds = widget.getBounds();
		return bounds == null ? NO_BOUNDS : bounds;
	}

	private static String describeSnapshot(int[] ids, int[] quantities)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] <= 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(i).append('=').append(ids[i]).append('x').append(quantities[i]);
		}
		return sb.length() == 0 ? "empty" : sb.toString();
	}

	private static String describeArrangement(int[] ids, int[] target)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < target.length; i++)
		{
			if (ids[i] <= 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(i).append("->").append(target[i]);
		}
		return sb.length() == 0 ? "empty" : sb.toString();
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import java.awt.Rectangle;

/**
 * One cell of the bag view as the pure tier sees it: which slot index it is, what item (if any)
 * it currently shows, and where the game drew it. Built from the widget children on the client
 * thread; never holds a widget reference.
 */
public final class BagSlot
{
	public final int index;
	public final int itemId;
	public final int quantity;
	public final Rectangle bounds;

	public BagSlot(int index, int itemId, int quantity, Rectangle bounds)
	{
		this.index = index;
		this.itemId = itemId;
		this.quantity = quantity;
		this.bounds = bounds;
	}

	public boolean isEmpty()
	{
		return itemId <= 0;
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The drag ghost: the dragged item's image following the cursor, plus a highlight outline around
 * the hovered target cell. Draws nothing unless {@link BagViewController}'s model reports a drag
 * in progress; renders the source cell's item exactly as it last stood in {@link
 * BagViewController#getSlots()}, since the source cell keeps rendering in place while a drag is
 * active.
 *
 * <p>{@code render} runs on the client thread, so it is safe to read {@link BagViewController}'s
 * model and published state directly here; unlike {@link BagInputListener}, this class never
 * touches the AWT-only fields the input listener keeps for itself.
 */
@Slf4j
@Singleton
public class BagDragOverlay extends Overlay
{
	private static final float GHOST_ALPHA = 0.6f;
	private static final Color HIGHLIGHT_COLOR = new Color(255, 255, 255, 160);

	private final Client client;
	private final ItemManager itemManager;
	private final BagViewController controller;

	/** Debug-logged only on the start/stop edge, never per frame. */
	private boolean rendering;

	@Inject
	public BagDragOverlay(Client client, ItemManager itemManager, BagViewController controller)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.controller = controller;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BagViewModel model = controller.getModel();
		if (!controller.isViewOpen() || !model.isDragging())
		{
			setRendering(false);
			return null;
		}

		setRendering(true);

		int hoverSlot = model.getHoverSlot();
		if (hoverSlot >= 0)
		{
			Rectangle cell = BagGeometry.cell(hoverSlot, controller.getGridBounds());
			graphics.setColor(HIGHLIGHT_COLOR);
			graphics.drawRect(cell.x, cell.y, cell.width - 1, cell.height - 1);
		}

		Point dragPoint = model.getDragPoint();
		if (dragPoint != null)
		{
			drawGhost(graphics, model.getDragSource(), dragPoint);
		}

		return null;
	}

	/** Draws the dragged item's image centred on the cursor at reduced alpha. */
	private void drawGhost(Graphics2D graphics, int sourceSlot, Point cursor)
	{
		List<BagSlot> slots = controller.getSlots();
		if (sourceSlot < 0 || sourceSlot >= slots.size())
		{
			return;
		}

		BagSlot slot = slots.get(sourceSlot);
		if (slot.isEmpty())
		{
			return;
		}

		ItemComposition composition = client.getItemDefinition(slot.itemId);
		boolean stackable = composition != null && composition.isStackable();
		BufferedImage image = itemManager.getImage(slot.itemId, slot.quantity, stackable);
		if (image == null)
		{
			return;
		}

		int x = cursor.x - image.getWidth() / 2;
		int y = cursor.y - image.getHeight() / 2;

		Composite old = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, GHOST_ALPHA));
		graphics.drawImage(image, x, y, null);
		graphics.setComposite(old);
	}

	private void setRendering(boolean now)
	{
		if (now == rendering)
		{
			return;
		}
		rendering = now;
		log.debug("Bag drag ghost {}", now ? "started rendering" : "stopped rendering");
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import java.awt.Rectangle;

/**
 * Pure grid arithmetic for the looting bag's item grid ({@code WildernessLootingbag.ITEMS},
 * group 81 child 5). Facts verified against the live cache and clientscript 497; see
 * {@code docs/RESEARCH.md} section 1.
 *
 * <p>4 columns, cells 36x32, filled top-left in container order with an 8px gutter between
 * columns:
 *
 * <pre>
 * x(slot) = (slot % 4) * 44        y(slot) = (slot / 4) * 32
 * </pre>
 *
 * <p>Never hit-tests widget children directly: empty cells are hidden at 0x0 by the game and
 * cannot be hit, so every drop target comes from this arithmetic on the canvas bounds of the
 * grid layer instead.
 */
public final class BagGeometry
{
	public static final int COLS = 4;
	public static final int ROWS = 7;
	public static final int SLOTS = 28;
	public static final int CELL_W = 36;
	public static final int CELL_H = 32;
	public static final int PITCH_X = 44;
	public static final int PITCH_Y = 32;

	private BagGeometry()
	{
	}

	/**
	 * Child-local x of the given slot's cell, i.e. what the game itself sets with
	 * {@code cc_setposition} for an occupied slot.
	 */
	public static int x(int slot)
	{
		return (slot % COLS) * PITCH_X;
	}

	/**
	 * Child-local y of the given slot's cell.
	 */
	public static int y(int slot)
	{
		return (slot / COLS) * PITCH_Y;
	}

	/**
	 * Canvas rectangle of the given slot's cell, given the canvas bounds of the grid layer
	 * ({@code 81:5}).
	 */
	public static Rectangle cell(int slot, Rectangle gridBounds)
	{
		return new Rectangle(gridBounds.x + x(slot), gridBounds.y + y(slot), CELL_W, CELL_H);
	}

	/**
	 * The slot whose pitch cell contains the given canvas point, or {@code -1} if the point is
	 * outside the 4x7 pitch rectangle. A point in the gutter between columns belongs to the
	 * column on its left, since the divide is by pitch, not by cell width.
	 */
	public static int slotAt(Rectangle gridBounds, int canvasX, int canvasY)
	{
		int relX = canvasX - gridBounds.x;
		int relY = canvasY - gridBounds.y;

		if (relX < 0 || relY < 0)
		{
			return -1;
		}

		int col = relX / PITCH_X;
		int row = relY / PITCH_Y;

		if (col >= COLS || row >= ROWS)
		{
			return -1;
		}

		return row * COLS + col;
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;

/**
 * All mouse and Escape-key input for the looting bag grid. Runs on the AWT event thread and never
 * touches {@link BagViewModel} directly: it decides whether to consume purely from the volatiles
 * {@link BagViewController} publishes each client-thread pass ({@link
 * BagViewController#isViewOpen()}, {@link BagViewController#getGridBounds()}, {@link
 * BagViewController#getSlots()}), and posts every mutation with {@link
 * BagViewController#post(Runnable)} so it runs on the client thread at the top of the next frame.
 *
 * <p>Registered at mouse-listener position 0, ahead of the game's own handling, so a consumed
 * press never reaches the client's mouse buffer: nothing is written into the world, so nothing
 * triggers the modal close that would otherwise dismiss the interface.
 *
 * <p>Right button and mouse-move are never consumed, so {@code Examine}, the value tooltip and
 * hover tooltips keep working exactly as they do on an unmodified client. Alt is respected too, so
 * alt-dragging other RuneLite overlays over the bag keeps working.
 *
 * <h2>Coordinate space</h2>
 *
 * <p>Position 0 is also where core's {@code StretchedModePlugin} inserts its
 * {@code TranslateMouseListener}, and {@code MouseManager.registerMouseListener(int, l)} is a list
 * insert, so whichever of us registered there most recently runs first. We do not control that
 * ordering. When Translate runs ahead of us the {@link MouseEvent} we receive is already
 * game-canvas space; when it runs behind us (e.g. immediately after we re-enable) the event still
 * carries raw, stretched canvas pixels. Widget bounds are always game space, so hit-testing the
 * raw event is wrong in the second ordering and scaling it unconditionally is wrong in the first.
 *
 * <p>Hit-testing {@link Client#getMouseCanvasPosition()} instead looked like a way to sidestep the
 * question entirely, but the shipped client's bytecode disproves it: the client updates that
 * tracked position <b>after</b> the whole {@code MouseManager} chain has run and <b>only when the
 * event comes back unconsumed</b>. We consume every {@code MOUSE_DRAGGED}, so during our own drag
 * the getter freezes at the press point, the 4px slop is never crossed and the drag silently does
 * nothing.
 *
 * <p>So the space is measured once per gesture instead of assumed:
 *
 * <ul>
 *   <li>At {@link #mousePressed} the tracked position <i>is</i> fresh, because AWT always delivers
 *       an unconsumed {@code MOUSE_MOVED} before a press and a press does not move the pointer.
 *       We compare the raw event coordinates and their translated counterpart against it and latch
 *       whichever is closer into {@link #eventsArePreTranslate} for the rest of the gesture. One
 *       boolean, nothing more: a single sample cannot separate scale from offset, so no scale is
 *       ever inferred from the comparison.</li>
 *   <li>The scale itself is read from the client
 *       ({@link Client#isStretchedEnabled()}, {@link Client#getStretchedDimensions()},
 *       {@link Client#getRealDimensions()}) with exactly the formula core's
 *       {@code TranslateMouseListener.translateEvent} uses, and re-read on every event the same
 *       way core does, so a window resized mid-gesture is handled with the scale current at each
 *       event rather than a stale one.</li>
 *   <li>Every subsequent drag and release resolves its game-space point from its own event
 *       coordinates via {@link #gamePoint}, so nothing depends on the client updating a value our
 *       own consumption prevents it from updating.</li>
 * </ul>
 *
 * <p>Reading these {@code Client} getters from the AWT thread is a deliberate, narrow exception to
 * this codebase's "Client access on the client thread" rule of thumb. They are stateless value
 * reads with no side effects, and core reads the same three dimension getters from this very
 * thread, in this very listener chain, in {@code TranslateMouseListener}.
 *
 * <p>Every hit-test decision below logs both coordinate spaces, and the press logs the latched
 * orientation and the scale it used. That logging is how this ordering bug was originally caught.
 */
@Slf4j
@Singleton
public class BagInputListener implements MouseListener, KeyListener
{
	private static final int DRAG_SLOP = 4;

	/** Scale factors when nothing is being stretched: {@code x}, then {@code y}. */
	private static final double[] NO_STRETCH = {1.0d, 1.0d};

	private final BagViewController controller;
	private final Client client;

	// AWT thread only. Armed by a left press on an occupied slot inside the grid; becomes active
	// once the drag crosses the slop, at which point beginDrag has been posted to the controller.
	private boolean dragArmed;
	private boolean dragActive;
	private int sourceSlot = -1;
	private Point pressPoint;

	/**
	 * Latched at every press, for the duration of that one gesture: true when this event stream is
	 * being delivered to us <i>before</i> core's {@code TranslateMouseListener} has run, i.e. the
	 * coordinates are raw stretched-canvas pixels and we must translate them ourselves. False when
	 * the events already arrive in game-canvas space (Translate ran ahead of us, or nothing is
	 * being stretched), in which case {@link #gamePoint} is the identity. See the class javadoc.
	 */
	private boolean eventsArePreTranslate;

	/** True while a press we consumed is outstanding, so its release is consumed too. */
	private boolean pressConsumed;

	/**
	 * True when the press+release that precede the next click were consumed. AWT delivers pressed,
	 * released, then clicked, so {@link #pressConsumed} has already been cleared by the time the
	 * click arrives; an unconsumed click reaches the client's mouse buffer and can drive the world
	 * interaction that dismisses this modal-clickthrough window (docs/RESEARCH.md section 1, "Why
	 * the window closes on the next interaction"). Same two-flag pattern as bankless-bank's
	 * {@code BankInputListener}.
	 */
	private boolean clickConsumed;

	@Inject
	public BagInputListener(BagViewController controller, Client client)
	{
		this.controller = controller;
		this.client = client;
	}

	/**
	 * The client's own tracked pointer position, in game-canvas space. Fresh at press time only
	 * (see the class javadoc); never used for a drag or a release, where our own consumption stops
	 * the client from advancing it. Cannot be null in the real client -- the getter allocates a
	 * fresh {@code Point} from two volatile ints -- but it reports {@code (-1, -1)} while the
	 * pointer is off the canvas, which simply fails every grid hit test.
	 */
	private Point canvasPoint()
	{
		net.runelite.api.Point p = client.getMouseCanvasPosition();
		return p == null ? new Point(-1, -1) : new Point(p.getX(), p.getY());
	}

	/**
	 * The stretched-canvas to game-canvas scale, read live from the client, exactly as core's
	 * {@code TranslateMouseListener.translateEvent} computes it. Never inferred from a ratio of
	 * observed coordinates: one sample cannot separate a scale from an offset, and the ratio
	 * degenerates near the origin. Returns {@link #NO_STRETCH} whenever nothing is being stretched
	 * or the client's dimensions are unusable.
	 */
	private double[] stretchScale()
	{
		if (!client.isStretchedEnabled())
		{
			return NO_STRETCH;
		}

		Dimension stretched = client.getStretchedDimensions();
		Dimension real = client.getRealDimensions();

		if (stretched == null || real == null
			|| stretched.width <= 0 || stretched.height <= 0
			|| real.getWidth() <= 0 || real.getHeight() <= 0)
		{
			return NO_STRETCH;
		}

		return new double[]{stretched.width / real.getWidth(), stretched.height / real.getHeight()};
	}

	/** The event's coordinates put through {@code scale}, i.e. what Translate would make of them. */
	private static Point translate(MouseEvent e, double[] scale)
	{
		return new Point((int) (e.getX() / scale[0]), (int) (e.getY() / scale[1]));
	}

	private static int manhattan(Point a, Point b)
	{
		return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
	}

	/**
	 * Game-space coordinates of a drag or release event, using the orientation latched at press and
	 * the scale current at this event. Identity whenever the events already arrive translated.
	 */
	private Point gamePoint(MouseEvent e)
	{
		return eventsArePreTranslate ? translate(e, stretchScale()) : new Point(e.getX(), e.getY());
	}

	private boolean insideGrid(Point game, boolean altDown)
	{
		return controller.isViewOpen() && !altDown && controller.getGridBounds().contains(game);
	}

	private void clearDragState()
	{
		dragArmed = false;
		dragActive = false;
		sourceSlot = -1;
		pressPoint = null;
	}

	private static MouseEvent consume(MouseEvent e)
	{
		e.consume();
		return e;
	}

	// ---- mouse -----------------------------------------------------------------------------

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		// Never consumed: hover tooltips (qty x price = total, docs/RESEARCH.md section 1 point 7)
		// are untouched, and it is the unconsumed move stream that keeps the client's tracked
		// pointer position fresh for the next press, which is what we latch the coordinate
		// orientation from.
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		pressConsumed = false;
		clickConsumed = false;
		clearDragState();

		// The one point in the gesture where the client's tracked position is provably fresh, so
		// the one point where we can tell which space we are being handed (class javadoc).
		Point canvas = canvasPoint();
		double[] scale = stretchScale();
		Point translated = translate(e, scale);
		int rawDelta = manhattan(new Point(e.getX(), e.getY()), canvas);
		int translatedDelta = manhattan(translated, canvas);
		eventsArePreTranslate = translatedDelta < rawDelta;

		Point game = eventsArePreTranslate ? translated : new Point(e.getX(), e.getY());

		log.debug("Bag press latched preTranslate={} (stretched={}, scale={}x{}): awt=({}, {}) "
				+ "translated=({}, {}) canvas=({}, {}) rawDelta={} translatedDelta={}",
			eventsArePreTranslate, client.isStretchedEnabled(), scale[0], scale[1],
			e.getX(), e.getY(), translated.x, translated.y, canvas.x, canvas.y,
			rawDelta, translatedDelta);

		boolean insideGrid = insideGrid(canvas, e.isAltDown());

		if (!SwingUtilities.isLeftMouseButton(e) || !insideGrid)
		{
			log.debug("Bag press at awt=({}, {}) game=({}, {}) canvas=({}, {}) not consumed (leftButton={}, insideGrid={})",
				e.getX(), e.getY(), game.x, game.y, canvas.x, canvas.y,
				SwingUtilities.isLeftMouseButton(e), insideGrid);
			return e;
		}

		Rectangle bounds = controller.getGridBounds();
		int slot = BagGeometry.slotAt(bounds, canvas.x, canvas.y);
		boolean occupied = slot >= 0 && slot < controller.getSlots().size()
			&& !controller.getSlots().get(slot).isEmpty();

		pressConsumed = true;
		if (occupied)
		{
			dragArmed = true;
			sourceSlot = slot;
			// Baseline for the slop in the same space every later event resolves into, so the two
			// can never differ by a translation-rounding pixel.
			pressPoint = game;
		}

		log.debug("Bag press at awt=({}, {}) game=({}, {}) canvas=({}, {}) resolved to slot {} (occupied={}), consumed=true",
			e.getX(), e.getY(), game.x, game.y, canvas.x, canvas.y, slot, occupied);

		return consume(e);
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (!dragArmed || pressPoint == null)
		{
			// Not our press (outside the grid, alt held, right button, or an empty-slot press with
			// nothing to drag): consumed only if the press that started it was.
			return pressConsumed ? consume(e) : e;
		}

		// Never the tracked canvas position here: we consume drags, so the client never advances
		// it and it would stay frozen at the press point for the whole gesture.
		Point game = gamePoint(e);

		if (!dragActive)
		{
			if (Math.abs(game.x - pressPoint.x) < DRAG_SLOP && Math.abs(game.y - pressPoint.y) < DRAG_SLOP)
			{
				log.debug("Bag drag from slot {} still within the slop at awt=({}, {}) game=({}, {}) (press was at ({}, {}))",
					sourceSlot, e.getX(), e.getY(), game.x, game.y, pressPoint.x, pressPoint.y);
				return consume(e);
			}

			dragActive = true;
			int source = sourceSlot;
			log.debug("Bag drag from slot {} crossed the slop at awt=({}, {}) game=({}, {}); posting beginDrag",
				source, e.getX(), e.getY(), game.x, game.y);
			controller.post(() -> controller.beginDrag(source));
		}

		int hoverSlot = BagGeometry.slotAt(controller.getGridBounds(), game.x, game.y);
		log.debug("Bag drag from slot {} moved to awt=({}, {}) game=({}, {}), resolved to slot {}, consumed=true",
			sourceSlot, e.getX(), e.getY(), game.x, game.y, hoverSlot);
		controller.post(() -> controller.updateDrag(game));

		return consume(e);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		boolean consumed = pressConsumed;

		if (dragActive)
		{
			Point game = gamePoint(e);
			int target = BagGeometry.slotAt(controller.getGridBounds(), game.x, game.y);
			log.debug("Bag drag from slot {} released at awt=({}, {}) game=({}, {}), resolved to slot {}, consumed={}",
				sourceSlot, e.getX(), e.getY(), game.x, game.y, target, consumed);
			controller.post(() -> controller.endDrag(target));
		}
		else if (dragArmed)
		{
			// Armed but never crossed the slop: nothing was ever begun, so there is nothing to end.
			Point game = gamePoint(e);
			log.debug("Bag press on slot {} released at awt=({}, {}) game=({}, {}) without a drag, consumed={}",
				sourceSlot, e.getX(), e.getY(), game.x, game.y, consumed);
		}

		clearDragState();
		clickConsumed = consumed;
		pressConsumed = false;

		return consumed ? consume(e) : e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		boolean consumed = clickConsumed;
		clickConsumed = false;
		return consumed ? consume(e) : e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	// ---- keyboard --------------------------------------------------------------------------

	@Override
	public void keyTyped(KeyEvent e)
	{
		// Nothing of ours is ever typed into.
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (e.getKeyCode() != KeyEvent.VK_ESCAPE || !dragArmed)
		{
			// Not dragging: left to the game, which closes the interface on Escape as normal.
			return;
		}

		log.debug("Escape cancelled the bag drag from slot {}", sourceSlot);
		controller.post(controller::cancelDrag);
		clearDragState();
		pressConsumed = false;
		clickConsumed = false;
		e.consume();
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// Nothing: the cancel already happened on keyPressed.
	}

	@Override
	public void focusLost()
	{
		if (dragArmed)
		{
			log.debug("Focus lost; cancelling the bag drag from slot {}", sourceSlot);
			controller.post(controller::cancelDrag);
		}
		clearDragState();
		pressConsumed = false;
		clickConsumed = false;
	}
}

package io.robrichardson.lootingbagorganizer.ui;

import io.robrichardson.lootingbagorganizer.model.BagLayout;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.Arrays;

/**
 * Pure tier. Owns a {@link BagLayout} and the current bag snapshot, resolves which item lands in
 * which slot, hit-tests the mouse against {@link BagSlot} bounds, and tracks drag state.
 *
 * <p>No RuneLite, Swing or Graphics2D imports: only {@code java.util}, {@code java.awt.Point} /
 * {@code Rectangle} as headless value types, and {@code model.*}. Unit tested with plain JUnit 4.
 */
public class BagViewModel
{
	private static final int NONE = -1;

	private BagLayout layout = new BagLayout();
	private boolean layoutChanged;

	/**
	 * What the last {@link #arrange(int[])} put in each display slot, {@code -1} for an empty cell.
	 * The layout only ever stores deliberate placements, so this is the only record of which item
	 * an auto-placed cell is showing, and {@link #endDrag(int)} needs it to pin what a drag touches.
	 */
	private final int[] displayItemIds = newEmptyDisplay();

	private Rectangle gridBounds;
	private boolean dragging;
	private int dragSource = NONE;
	private Point dragPoint;
	private int hoverSlot = NONE;
	private int lastFreezeCount;

	public BagLayout getLayout()
	{
		return layout;
	}

	public void setLayout(BagLayout layout)
	{
		this.layout = layout;
	}

	/**
	 * Resolves each container slot to a display slot per the saved layout's placement rules.
	 *
	 * <p>Pass 1 places pinned ids: for each layout slot in ascending index order that reserves an
	 * item id, the first unclaimed container copy of that id (ascending container index) claims it.
	 * Pass 2 places every remaining container item, in ascending container index order, into the
	 * lowest-index display slot that is neither taken nor reserved by an as-yet-unfulfilled pin; if
	 * every remaining slot is reserved, the lowest-index reserved-but-unfulfilled slot is used
	 * instead and that reservation is dropped from the layout (see {@link #consumeLayoutChanged()}).
	 *
	 * @param containerItemIds raw container 516 contents; {@code <= 0} means an empty container slot
	 * @return one entry per input entry: the display slot it resolves to, or {@code -1} for an empty
	 * container slot. The non -1 entries are a permutation: no display slot is used twice.
	 */
	public int[] arrange(int[] containerItemIds)
	{
		int length = containerItemIds.length;
		int[] result = new int[length];
		boolean[] taken = new boolean[BagLayout.SLOTS];
		boolean[] reserved = new boolean[BagLayout.SLOTS];
		boolean[] containerClaimed = new boolean[length];

		Arrays.fill(displayItemIds, -1);

		for (int slot = 0; slot < BagLayout.SLOTS; slot++)
		{
			if (layout.slotAt(slot) != null)
			{
				reserved[slot] = true;
			}
		}

		// Pass 1: pinned ids claim the first unclaimed container copy of their id.
		for (int slot = 0; slot < BagLayout.SLOTS; slot++)
		{
			Integer pinnedId = layout.slotAt(slot);
			if (pinnedId == null)
			{
				continue;
			}
			for (int i = 0; i < length; i++)
			{
				if (!containerClaimed[i] && !isEmpty(containerItemIds[i]) && containerItemIds[i] == pinnedId)
				{
					containerClaimed[i] = true;
					taken[slot] = true;
					result[i] = slot;
					displayItemIds[slot] = containerItemIds[i];
					break;
				}
			}
		}

		// Pass 2: everything else, in container order, into the lowest free unreserved slot; falls
		// back to the lowest free reserved slot (dropping that reservation) when the bag needs it.
		for (int i = 0; i < length; i++)
		{
			if (isEmpty(containerItemIds[i]))
			{
				result[i] = -1;
				continue;
			}
			if (containerClaimed[i])
			{
				continue;
			}

			int target = firstFree(taken, reserved, false);
			if (target == -1)
			{
				target = firstFree(taken, reserved, true);
				if (target != -1)
				{
					layout.clearSlot(target);
					reserved[target] = false;
					layoutChanged = true;
				}
			}

			// Every input slot beyond BagLayout.SLOTS has nowhere left to go; leave it unplaced.
			result[i] = target;
			if (target != -1)
			{
				taken[target] = true;
				containerClaimed[i] = true;
				displayItemIds[target] = containerItemIds[i];
			}
		}

		return result;
	}

	/**
	 * Reports whether the most recent {@link #arrange(int[])} had to drop a stale reservation to
	 * fit every item in, then resets the flag. One-shot: a second call in a row returns
	 * {@code false} unless another {@code arrange} call has run in between.
	 */
	public boolean consumeLayoutChanged()
	{
		boolean changed = layoutChanged;
		layoutChanged = false;
		return changed;
	}

	private static boolean isEmpty(int itemId)
	{
		return itemId <= 0;
	}

	private static int firstFree(boolean[] taken, boolean[] reserved, boolean allowReserved)
	{
		for (int slot = 0; slot < BagLayout.SLOTS; slot++)
		{
			if (taken[slot])
			{
				continue;
			}
			if (!allowReserved && reserved[slot])
			{
				continue;
			}
			return slot;
		}
		return -1;
	}

	/**
	 * Canvas bounds of the grid layer ({@code 81:5}), used to resolve {@link #slotAt(Point)} and
	 * drag hover. Published by the controller each client-thread pass.
	 */
	public void setGridBounds(Rectangle gridBounds)
	{
		this.gridBounds = gridBounds;
	}

	/**
	 * The slot whose pitch cell contains the given canvas point, or {@code -1} if the point is
	 * outside the grid or no grid bounds have been published yet. Pure delegation to
	 * {@link BagGeometry#slotAt(Rectangle, int, int)}; empty cells are hidden by the game at 0x0
	 * and cannot be hit-tested directly (docs/RESEARCH.md section 2, "Empty slots as drop
	 * targets").
	 */
	public int slotAt(Point p)
	{
		if (gridBounds == null)
		{
			return NONE;
		}
		return BagGeometry.slotAt(gridBounds, p.x, p.y);
	}

	/**
	 * Arms a drag from an occupied slot. Called once the AWT listener's press has moved past the
	 * slop threshold. The source cell keeps rendering in place; only the overlay reacts to this
	 * state.
	 */
	public void beginDrag(int sourceSlot)
	{
		dragging = true;
		dragSource = sourceSlot;
		dragPoint = null;
		hoverSlot = sourceSlot;
	}

	/** Tracks the cursor while a drag is active, updating the hovered target slot. */
	public void updateDrag(Point canvas)
	{
		if (!dragging)
		{
			return;
		}
		dragPoint = canvas;
		hoverSlot = slotAt(canvas);
	}

	/**
	 * Resolves a drop. Dropping outside the grid ({@code targetSlot == -1}) or back onto the
	 * source slot cancels with no change. Otherwise the two slots are swapped via
	 * {@link BagLayout#moveSlot(int, int)} — a move when the target was empty, a swap when it was
	 * occupied — and both slots end up pinned in the layout, since a drag is always a deliberate
	 * placement.
	 *
	 * @return {@code true} if the layout changed; {@code false} for a cancel, an out-of-grid drop,
	 * or a call with no drag in progress
	 */
	public boolean endDrag(int targetSlot)
	{
		if (!dragging)
		{
			return false;
		}

		int source = dragSource;
		cancelDrag();

		if (targetSlot == NONE || targetSlot == source)
		{
			lastFreezeCount = 0;
			return false;
		}

		if (isGenuinelyEmpty(source) && isGenuinelyEmpty(targetSlot))
		{
			// Two genuinely empty, unreserved cells: nothing to move, nothing to freeze.
			lastFreezeCount = 0;
			return false;
		}

		// A drag is always a deliberate placement. Editing the layout for the first time turns the
		// bag from "auto-arranged" to "player-arranged": every currently displayed item has to be
		// pinned to its display slot first, not just the two slots the drag touches. Otherwise the
		// slot the dragged item vacated stays unreserved, and the next arrange's free-slot pass
		// (docs/RESEARCH.md section 4, "new items take the first free slot in container order")
		// slides every later, untouched item forward to fill the gap.
		lastFreezeCount = freezeDisplayedArrangement();

		layout.moveSlot(source, targetSlot);
		return true;
	}

	/** A slot with no reservation and nothing currently displayed in it. */
	private boolean isGenuinelyEmpty(int slot)
	{
		return layout.slotAt(slot) == null && displayItemIds[slot] <= 0;
	}

	/**
	 * Pins every currently displayed item to the slot it is showing in, so the imminent move/swap
	 * cannot leave a gap that {@link #arrange(int[])} would fill by shifting later items forward.
	 * A no-op for slots that are already a deliberate placement or reservation, or that are
	 * genuinely empty. Called once per {@link #endDrag(int)} that goes on to change the layout.
	 *
	 * @return the number of slots this call newly pinned, for logging
	 */
	private int freezeDisplayedArrangement()
	{
		int frozen = 0;
		for (int slot = 0; slot < BagLayout.SLOTS; slot++)
		{
			if (layout.slotAt(slot) != null)
			{
				continue;
			}
			int shown = displayItemIds[slot];
			if (shown > 0)
			{
				layout.setSlot(slot, shown);
				frozen++;
			}
		}
		return frozen;
	}

	private static int[] newEmptyDisplay()
	{
		int[] display = new int[BagLayout.SLOTS];
		Arrays.fill(display, -1);
		return display;
	}

	/** Clears any in-flight drag without touching the layout. */
	public void cancelDrag()
	{
		dragging = false;
		dragSource = NONE;
		dragPoint = null;
		hoverSlot = NONE;
	}

	public boolean isDragging()
	{
		return dragging;
	}

	public int getDragSource()
	{
		return dragSource;
	}

	public Point getDragPoint()
	{
		return dragPoint;
	}

	public int getHoverSlot()
	{
		return hoverSlot;
	}

	/**
	 * How many previously auto-placed slots the most recent layout-changing {@link #endDrag(int)}
	 * had to freeze into deliberate placements before applying the move/swap. {@code 0} after a
	 * cancelled or no-op drag. For the controller's drag log, not behaviour.
	 */
	public int getLastFreezeCount()
	{
		return lastFreezeCount;
	}
}

